sect2.example:
   isset su una proprietà con un hook get


<?php
class Article
{
    public ?string $title = null {
        get => $this->title ?? 'Untitled';
    }

    public string $author {
        get => ucfirst($this->author);
        set => $this->author = $value;
    }
}

$article = new Article();

// Il valore di supporto è null, ma l'hook get restituisce 'Untitled'.
var_dump(isset($article->title));

// L'hook get legge un valore di supporto non inizializzato.
try {
    var_dump(isset($article->author));
} catch (Error $e) {
    echo $e->getMessage(), "\n";
}
?>


   &example.outputs;


bool(true)
Typed property Article::$author must not be accessed before initialization

   Gestione di un valore di supporto non inizializzato


<?php
class Article
{
    // Inizializzare il valore di supporto evita l'errore.
    public ?string $subtitle = null {
        get => $this->subtitle !== null ? ucfirst($this->subtitle) : null;
    }

    // L'hook get controlla il proprio valore di supporto.
    public string $author {
        get => isset($this->author) ? ucfirst($this->author) : 'Anonymous';
        set => $this->author = $value;
    }
}

$article = new Article();

var_dump(isset($article->subtitle));
var_dump(isset($article->author));
var_dump($article->author);
?>


   &example.outputs;


bool(false)
bool(true)
string(9) "Anonymous"

   unset su una proprietà con hook


<?php
class Rectangle
{
    public int $area {
        get => $this->h * $this->w;
    }

    public function __construct(public int $h, public int $w) {}
}

$r = new Rectangle(4, 5);

try {
    unset($r->area);
} catch (Error $e) {
    echo $e->getMessage(), "\n";
}
?>


   &example.outputs;


Cannot unset hooked property Rectangle::$area
